import React, { useEffect, useState, useRef } from "react";
import axios from "axios";
import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";

// Axios Default Authorization Header
const token = localStorage.getItem("authToken");
const API = axios.create({
  baseURL: "http://localhost:8080",
  headers: {
    Authorization: `Bearer ${token}`,
    "Content-Type": "application/json",
  },
});

export default function LudoBoard() {
  const [boardState, setBoardState] = useState(null);
  const [diceValue, setDiceValue] = useState(null);
  const [status, setStatus] = useState("");
  const stompClientRef = useRef(null);
  const autoCancelRef = useRef(null);
  const sessionId = localStorage.getItem("currentSessionId");

  // WebSocket কানেকশন
  useEffect(() => {
    const socket = new SockJS(
      `http://localhost:8080/ludo-ws?token=${token}`
    );
    const client = new Client({
      webSocketFactory: () => socket,
      onConnect: () => {
        client.subscribe(`/topic/game/${sessionId}`, (message) => {
          const state = JSON.parse(message.body);
          setBoardState(state);
        });
      },
    });
    client.activate();
    stompClientRef.current = client;
    return () => client.deactivate();
  }, [sessionId]);

  // ডাইস রোল
  const rollDice = async () => {
    await API.post(`/api/match/rollDice/${sessionId}`);
    const dice = Math.floor(Math.random() * 6) + 1;
    setDiceValue(dice);
    resetAutoCancel();
  };

  // ৬০ সেকেন্ড ইনঅ্যাক্টিভ হলে অটো-ক্যানসেল
  const resetAutoCancel = () => {
    if (autoCancelRef.current) clearTimeout(autoCancelRef.current);
    autoCancelRef.current = setTimeout(async () => {
      setStatus("❌ ৬০ সেকেন্ডে ডাইস চালানো হয়নি, ম্যাচ ক্যানসেল");
      await API.get(`/api/match/status/${sessionId}`);
    }, 60000);
  };

  return (
    <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-6">
      <h2 className="text-3xl font-bold text-yellow-400 mb-6">🎯 Ludo Game</h2>

      {status && (
        <p className="bg-red-500 text-white px-4 py-2 rounded-lg mb-4 shadow">
          {status}
        </p>
      )}

      {boardState && (
        <pre className="bg-gray-800 text-green-400 p-4 rounded-lg shadow w-full max-w-lg overflow-x-auto">
          {JSON.stringify(boardState, null, 2)}
        </pre>
      )}

      <button
        onClick={rollDice}
        className="mt-6 px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl shadow-lg transition duration-200"
      >
        🎲 ডাইস চালাও
      </button>

      {diceValue && (
        <p className="mt-4 text-xl text-green-300 font-semibold">
          আপনি {diceValue} পেয়েছেন
        </p>
      )}
    </div>
  );
}
